using System;
using System.Linq;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MobCam;

/// <summary>The app icon (mobcam.ico, generated by scripts/make-icons.ps1) for the window and tray.</summary>
internal static class AppIcon
{
    private static readonly Uri IconUri = new("pack://application:,,,/mobcam.ico");

    /// <summary>Small icon for the notification area.</summary>
    public static System.Drawing.Icon Tray()
    {
        using var stream = Application.GetResourceStream(IconUri)!.Stream;
        return new System.Drawing.Icon(stream, System.Windows.Forms.SystemInformation.SmallIconSize);
    }

    /// <summary>Largest frame of the icon, for the window and the header logo.</summary>
    public static ImageSource Image()
    {
        var decoder = new IconBitmapDecoder(IconUri, BitmapCreateOptions.None, BitmapCacheOption.OnLoad);
        return decoder.Frames.OrderByDescending(f => f.PixelWidth).First();
    }
}
